{
  "decisions": {
    "P0079F0001": {
      "action": "duplicate",
      "representative_fact_id": "P0079F0004",
      "corrections": [],
      "reason": "P0079F0001의 Pinned Memory DMA 디스크립터 생성 및 하드웨어 큐 제출 오버헤드(호출 1회당 약 1.0~1.5 μs)에 대한 설명·조건·한계·측정이 승인 후보 P0079F0004에 모두 포함되며, 별도 추가 주장이나 미해결 충돌이 없다."
    },
    "P0079F0002": {
      "action": "duplicate",
      "representative_fact_id": "P0079F0005",
      "corrections": [],
      "reason": "P0079F0002의 No-Pin Pageable 메모리에서 OS 페이징으로 인한 물리 주소 변경 가능성, GPU DMA 직접 읽기 불가, CPU L1/L2 캐시 memcpy, Pushbuffer 데이터 첨부 설명이 승인 후보 P0079F0005에 포함된다. 수치(0.02~0.05 μs, 30~50배)는 P0079F0004에 포함되지만, P0079F0002의 핵심 서술은 P0079F0005로 충분히 커버되며 별도 충돌은 없다. CPU 모델 언급은 원문(p79:e621)에 존재하나 승인 후보 요약에 생략되었을 뿐, 해석적 설명이라는 한계와 충돌하지 않는다."
    }
  }
}
